<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { api } from '@/api'; import type { Account,Category,Transaction,TransactionKind } from '@/types'
const items=ref<Transaction[]>([]), accounts=ref<Account[]>([]), categories=ref<Category[]>([]),saved=ref(''); const today=new Date().toISOString().slice(0,10); const form=ref<{accountId:string;categoryId:string;kind:TransactionKind;amount:number;occurredOn:string;description:string}>({accountId:'',categoryId:'',kind:'expense',amount:0,occurredOn:today,description:''})
const available=computed(()=>categories.value.filter(c=>c.appliesTo===form.value.kind&&!c.parentCategoryId)); const money=(v:number)=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(v); async function load(){[items.value,accounts.value,categories.value]=await Promise.all([api.transactions(),api.accounts(),api.categories()]);form.value.accountId ||=accounts.value[0]?.id??'';form.value.categoryId ||=available.value[0]?.id??''} async function save(){await api.createTransaction(form.value);saved.value='Zapisano transakcję.';form.value.amount=0;form.value.description='';await load()} onMounted(load)
</script>
<template><div class="grid two wide-first"><section class="panel"><div class="panel-title"><h2>Historia transakcji</h2><span>{{items.length}} wpisów</span></div><div class="transaction-row" v-for="t in items" :key="t.id"><span class="round-icon" :class="t.kind">{{t.kind==='expense'?'−':'+'}}</span><span>{{t.description||t.categoryName||'Bez opisu'}}<small>{{t.categoryName}} · {{t.accountName}} · {{t.occurredOn}}</small></span><strong :class="t.kind==='expense'?'negative':'positive'">{{t.kind==='expense'?'−':'+'}}{{money(t.amount)}}</strong></div><p v-if="!items.length" class="empty">Brak wpisów.</p></section><section class="panel"><h2>Nowa transakcja</h2><form @submit.prevent="save"><label>Rodzaj<select v-model="form.kind" @change="form.categoryId=available[0]?.id||''"><option value="expense">Wydatek</option><option value="income">Przychód</option></select></label><label>Konto<select v-model="form.accountId" required><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Kategoria<select v-model="form.categoryId" required><option v-for="c in available" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Kwota<input v-model.number="form.amount" min="0.01" step="0.01" type="number" required/></label><label>Data<input v-model="form.occurredOn" type="date" required/></label><label>Opis <input v-model.trim="form.description" placeholder="opcjonalnie"/></label><button class="button primary">Zapisz wpis</button><p class="success" v-if="saved">{{saved}}</p></form></section></div></template>
